  "popover": {
    dir: "popover",
    category: "atoms",
    examples: [
      { label: "Default", code: "<Popover\n  trigger=\"Open popover\"\n  title=\"Rename project\"\n  description=\"Choose a name your team will recognize.\"\n  actionLabel=\"Rename\"\n>\n  <Input label=\"Project name\" defaultValue=\"Identity Platform\" />\n</Popover>", render: e_atoms_popover_example_0 },
    ],
    donts: [
      { do: { caption: "Keep popovers compact: a focused prompt with one input and a clear action.", code: "<Popover inline title=\"Rename this project?\" actionLabel=\"Rename\">\n  <Input label=\"Project name\" defaultValue=\"Identity Platform\" />\n</Popover>", render: e_atoms_popover_dont_0_do }, dont: { caption: "A full form belongs in a dialog; in a floating popover it is cramped and easy to dismiss by accident.", code: "<View style={{ borderRadius: 6, borderWidth: 1, borderColor: tokens.border, backgroundColor: tokens.popover, padding: 16, ...shadow(\"md\"), alignSelf: \"flex-start\", minWidth: 260 }}>\n  <Input label=\"Name\" placeholder=\"Ada Lovelace\" style={{ marginBottom: 8 }} />\n  <Input label=\"Email\" placeholder=\"ada@canvas.dev\" style={{ marginBottom: 8 }} />\n  <View style={{ marginBottom: 8 }}>\n    <Text style={{ marginBottom: 6, fontSize: 14, lineHeight: 20, fontWeight: \"500\", color: tokens.foreground }}>Role</Text>\n    <Select defaultValue=\"Engineer\" options={[\"Engineer\", \"Designer\", \"Manager\"]} />\n  </View>\n  <Input label=\"Team\" placeholder=\"Identity Platform\" style={{ marginBottom: 8 }} />\n  <View style={{ flexDirection: \"row\", justifyContent: \"flex-end\", gap: 8 }}>\n    <Button outline small>Cancel</Button>\n    <Button primary small>Save</Button>\n  </View>\n</View>", render: e_atoms_popover_dont_0_dont } },
      { title: "Triggered", do: { caption: "Wrap the trigger in a relative anchor and dismiss on outside click so the panel positions and closes predictably.", code: "<Popover trigger=\"Open popover\" open description=\"Anchored to the trigger, closes on outside click.\" actionLabel=\"Close\" />", render: e_atoms_popover_dont_1_do }, dont: { caption: "A trigger with no relative anchor and no way to dismiss leaves the panel floating loose and stuck open.", code: "<View style={{ alignSelf: \"flex-start\" }}>\n  <Button outline small>Open popover</Button>\n  <View style={{ borderRadius: 6, borderWidth: 1, borderColor: tokens.border, backgroundColor: tokens.popover, padding: 16, ...shadow(\"md\"), marginTop: 8, minWidth: 240 }}>\n    <Text style={{ fontSize: 14, lineHeight: 20, color: tokens[\"popover-foreground\"] }}>No anchor, no dismiss, no Close.</Text>\n  </View>\n</View>", render: e_atoms_popover_dont_1_dont } },
      { title: "Inline", do: { caption: "Reserve the static panel for a brief always-on message with a single follow-up action.", code: "<Popover inline description=\"Saved to drafts. Publish when ready.\" actionLabel=\"Publish\" />", render: e_atoms_popover_dont_2_do }, dont: { caption: "An always-visible panel that scrolls internally is doing a card's or section's job; use the panel chrome only for short content.", code: "<View style={{ borderRadius: 6, borderWidth: 1, borderColor: tokens.border, backgroundColor: tokens.popover, padding: 16, ...shadow(\"md\"), maxHeight: 120, minWidth: 260, overflow: \"hidden\" }}>\n  <ScrollView style={{ maxHeight: 88 }}>\n    <Input label=\"Street\" placeholder=\"100 Market St\" style={{ marginBottom: 8 }} />\n    <Input label=\"City\" placeholder=\"San Francisco\" style={{ marginBottom: 8 }} />\n    <Input label=\"Region\" placeholder=\"California\" style={{ marginBottom: 8 }} />\n    <Input label=\"Postal code\" placeholder=\"94105\" style={{ marginBottom: 8 }} />\n  </ScrollView>\n</View>", render: e_atoms_popover_dont_2_dont } },
    ],
  },
