  "radio": {
    dir: "radio",
    category: "atoms",
    examples: [
      { label: "Default", code: "<RadioGroup defaultValue=\"pro\">\n  <Radio value=\"hobby\">Hobby</Radio>\n  <Radio value=\"pro\">Pro</Radio>\n  <Radio value=\"enterprise\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_example_0 },
      { label: "Inline", code: "<RadioGroup row defaultValue=\"hobby\">\n  <Radio value=\"hobby\">Hobby</Radio>\n  <Radio value=\"pro\">Pro</Radio>\n  <Radio value=\"enterprise\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_example_1 },
      { label: "Card", code: "<RadioGroup row defaultValue=\"pro\">\n  <Radio card value=\"hobby\" description=\"For personal projects.\">Hobby</Radio>\n  <Radio card value=\"pro\" description=\"For growing teams.\">Pro</Radio>\n  <Radio card value=\"enterprise\" description=\"Advanced security and support.\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_example_2 },
      { label: "With description", code: "<RadioGroup defaultValue=\"pro\">\n  <Radio value=\"hobby\" description=\"For personal projects and experiments.\">Hobby</Radio>\n  <Radio value=\"pro\" description=\"For growing teams that need more control.\">Pro</Radio>\n  <Radio value=\"enterprise\" description=\"Advanced security, compliance, and support.\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_example_3 },
    ],
    donts: [
      { do: { caption: "Pre-select a sensible default so the common path needs no clicks, and name the set with the group's own `label`.", code: "<RadioGroup label=\"Plan\" defaultValue=\"pro\">\n  <Radio value=\"hobby\">Hobby</Radio>\n  <Radio value=\"pro\">Pro</Radio>\n  <Radio value=\"enterprise\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_dont_0_do }, dont: { caption: "Leaving a radio group with nothing selected forces an extra decision and can submit empty.", code: "<View style={{ flexDirection: \"column\", gap: 8 }}>\n  <Text style={{ marginBottom: 4, fontSize: 14, lineHeight: 20, fontWeight: \"600\", color: tokens.foreground }}>Plan</Text>\n  <Radio>Hobby</Radio>\n  <Radio>Pro</Radio>\n  <Radio>Enterprise</Radio>\n</View>", render: e_atoms_radio_dont_0_dont } },
      { title: "Stacked", do: { caption: "Pass a `description` and the control stacks the title over its secondary line for you, ring aligned to the first text line.", code: "<Radio checked description=\"For growing teams that need more control.\">Pro</Radio>", render: e_atoms_radio_dont_1_do }, dont: { caption: "Center-aligning the control floats it to the vertical middle of a two-line label, leaving it visually unattached to the title it controls.", code: "<View style={{ flexDirection: \"column\", gap: 10 }}>\n  <View style={{ flexDirection: \"row\", alignItems: \"center\", gap: 8 }}>\n    <Radio checked />\n    <View>\n      <Text style={{ fontSize: 13, fontWeight: \"500\", color: tokens.foreground }}>Pro</Text>\n      <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>For growing teams that need more control.</Text>\n    </View>\n  </View>\n</View>", render: e_atoms_radio_dont_1_dont } },
      { title: "Inline", do: { caption: "Keep generous spacing between options and tighter spacing inside each so every label clearly pairs with its own control.", code: "<RadioGroup row defaultValue=\"hobby\">\n  <Radio value=\"hobby\" small>Hobby</Radio>\n  <Radio value=\"pro\" small>Pro</Radio>\n  <Radio value=\"enterprise\" small>Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_dont_2_do }, dont: { caption: "Cramped spacing between options makes each label blur into the next radio, so it is hard to tell which dot belongs to which choice.", code: "<View style={{ flexDirection: \"row\", flexWrap: \"wrap\", gap: 6 }}>\n  <Radio checked small>Hobby</Radio>\n  <Radio small>Pro</Radio>\n  <Radio small>Enterprise</Radio>\n</View>", render: e_atoms_radio_dont_2_dont } },
      { title: "Card", do: { caption: "Give the selected card a primary border and tinted fill so the whole tile reads as chosen, not just the dot. Pass `card` and the control derives that treatment from its checked state automatically.", code: "<RadioGroup row defaultValue=\"pro\">\n  <Radio card value=\"pro\" description=\"For growing teams.\">Pro</Radio>\n  <Radio card value=\"enterprise\" description=\"Advanced security.\">Enterprise</Radio>\n</RadioGroup>", render: e_atoms_radio_dont_3_do }, dont: { caption: "When the selected card keeps the same plain border, only the tiny native dot signals the choice and the active card is easy to miss.", code: "<View style={{ flexDirection: \"row\", gap: 8 }}>\n  <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\", flexDirection: \"column\", borderRadius: 6, borderWidth: 1, borderColor: tokens.border, padding: 14 }}>\n    <Radio checked style={{ marginBottom: 8 }} />\n    <Text style={{ fontSize: 13, fontWeight: \"600\", color: tokens.foreground }}>Pro</Text>\n    <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>For growing teams.</Text>\n  </View>\n  <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\", flexDirection: \"column\", borderRadius: 6, borderWidth: 1, borderColor: tokens.border, padding: 14 }}>\n    <Radio style={{ marginBottom: 8 }} />\n    <Text style={{ fontSize: 13, fontWeight: \"600\", color: tokens.foreground }}>Enterprise</Text>\n    <Text style={{ fontSize: 12, lineHeight: 16, color: tokens[\"muted-foreground\"] }}>Advanced security.</Text>\n  </View>\n</View>", render: e_atoms_radio_dont_3_dont } },
    ],
  },
