    category: "molecules",
    examples: [
      { label: "Default", code: "<DescriptionList\n  items={[\n    { term: \"Full name\", value: \"Rachel Chen\" },\n    { term: \"Email\", value: \"rachel.chen@example.com\" },\n    { term: \"Role\", value: \"Admin\" }\n  ]}\n/>", render: e_molecules_description_lists_example_0 },
      { label: "Card", code: "<DescriptionList\n  card\n  title=\"Application details\"\n  subtitle=\"Personal information and credentials.\"\n  items={[\n    { term: \"Full name\", value: \"Rachel Chen\" },\n    { term: \"Email\", value: \"rachel.chen@example.com\" },\n    { term: \"Role\", value: \"Admin\" }\n  ]}\n/>", render: e_molecules_description_lists_example_1 },
      { label: "Inline", code: "<DescriptionList\n  inline\n  items={[\n    { term: \"Status\", value: \"Active\" },\n    { term: \"Seats\", value: \"12 of 20\" },\n    { term: \"Renews\", value: \"Mar 1, 2026\" }\n  ]}\n/>", render: e_molecules_description_lists_example_2 },
      { label: "Rich values", code: "<DescriptionList\n  twoColumn\n  items={[\n    { term: \"Status\", value: \"Active\", status: true },\n    { term: \"Plan\", value: \"Pro\", badge: true },\n    { term: \"Members\", value: \"8 members\", avatars: [{ name: \"Rachel Chen\" }, { name: \"Alan Turing\" }, { name: \"Grace Hopper\" }], overflow: 5 },\n    { term: \"Client ID\", value: \"clnt_01H2X8K9\", mono: true, copyValue: \"clnt_01H2X8K9\" }\n  ]}\n/>", render: e_molecules_description_lists_example_3 },
      { label: "Inline-edit", code: "<DescriptionList\n  twoColumn\n  items={[\n    { term: \"Name\", value: \"Rachel Chen\", update: true },\n    { term: \"Email\", value: \"rachel.chen@example.com\", update: true }\n  ]}\n/>", render: e_molecules_description_lists_example_4 },
    ],
    donts: [
      { title: "Two-column", do: { caption: "Fix the label column wide enough for the longest term so every value lines up on one edge.", code: "<DescriptionList twoColumn divided items={[\n  { term: \"Client identifier\", value: \"clnt_01H2X8K9P3Q7VN4W6R5T0JYMZF\", mono: true },\n  { term: \"Status\", value: \"Active\", status: true }\n]} />", render: e_molecules_description_lists_dont_0_do }, dont: { caption: "A too-narrow label column wraps the longest term and knocks the two columns out of alignment.", code: "<View>\n  <View style={{ flexDirection: \"row\", alignItems: \"baseline\", gap: 16, borderBottomWidth: 1, borderColor: tokens.border, paddingVertical: 12 }}>\n    <Text style={{ width: 64, fontSize: 14, lineHeight: 20, color: tokens[\"muted-foreground\"] }}>Client identifier</Text>\n    <Text style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\", fontSize: 12.5, fontWeight: \"500\", color: tokens.foreground, fontFamily: \"monospace\" }}>clnt_01H2X8K9P3Q7VN4W6R5T0JYMZF</Text>\n  </View>\n  <View style={{ flexDirection: \"row\", alignItems: \"baseline\", gap: 16, paddingVertical: 12 }}>\n    <Text style={{ width: 64, fontSize: 14, lineHeight: 20, color: tokens[\"muted-foreground\"] }}>Status</Text>\n    <View style={{ flexGrow: 1, flexShrink: 1, flexBasis: \"0%\" }}>\n      <Badge status success>Active</Badge>\n    </View>\n  </View>\n</View>", render: e_molecules_description_lists_dont_0_dont } },
      { title: "Inline-edit", do: { caption: "Give every editable row a trailing Update affordance so the inline editor is discoverable; pressing it opens the editor in place, and Enter or Save commits.", code: "<DescriptionList twoColumn items={[\n  { term: \"Name\", value: \"Rachel Chen\", update: true },\n  { term: \"Email\", value: \"rachel.chen@example.com\", update: true }\n]} />", render: e_molecules_description_lists_dont_1_do }, dont: { caption: "Editable rows that look identical to read-only ones give no hint a value can be changed.", code: "<DescriptionList twoColumn items={[\n  { term: \"Name\", value: \"Rachel Chen\" },\n  { term: \"Email\", value: \"rachel.chen@example.com\" }\n]} />", render: e_molecules_description_lists_dont_1_dont } },
      { title: "Stacked", do: { caption: "Keep the label small, uppercase, and muted above a full-weight value so the data stays primary.", code: "<DescriptionList stacked items={[\n  { term: \"Full name\", value: \"Rachel Chen\" },\n  { term: \"Email\", value: \"rachel.chen@example.com\" }\n]} />", render: e_molecules_description_lists_dont_2_do }, dont: { caption: "Muting the value and bolding nothing inverts the hierarchy; the label outweighs the data it describes.", code: "<View style={{ maxWidth: 320, gap: 16 }}>\n  <View style={{ gap: 4 }}>\n    <Text style={{ fontSize: 14, lineHeight: 20, color: tokens.foreground }}>Full name</Text>\n    <Text style={{ fontSize: 14, lineHeight: 20, color: tokens[\"muted-foreground\"] }}>Rachel Chen</Text>\n  </View>\n  <View style={{ gap: 4 }}>\n    <Text style={{ fontSize: 14, lineHeight: 20, color: tokens.foreground }}>Email</Text>\n    <Text style={{ fontSize: 14, lineHeight: 20, color: tokens[\"muted-foreground\"] }}>rachel.chen@example.com</Text>\n  </View>\n</View>", render: e_molecules_description_lists_dont_2_dont } },
    ],
