  "drag-drop": {
    dir: "drag-drop",
    category: "organisms",
    examples: [
      { label: "Default", code: "<Stateful initial={[\n  { id: \"a\", zone: \"list\", title: \"Design review\" },\n  { id: \"b\", zone: \"list\", title: \"Write the tests\" },\n  { id: \"c\", zone: \"list\", title: \"Ship the release\" },\n]}>\n  {(cards, setCards) => (\n    <DragDropProvider>\n      <DropZone id=\"list\" label=\"Tasks\" onDrop={(e) => setCards(applyDrop(cards, e))}>\n        <Column snug>\n          {cards.map((c) => (\n            <Draggable key={c.id} id={c.id} data={c} label={c.title}>\n              <Card>\n                <Row between alignCenter>\n                  <Typography>{c.title}</Typography>\n                  <DragHandle label={`Reorder ${c.title}`} />\n                </Row>\n              </Card>\n            </Draggable>\n          ))}\n        </Column>\n      </DropZone>\n    </DragDropProvider>\n  )}\n</Stateful>", render: e_organisms_drag_drop_example_0 },
      { label: "Locked item", code: "<DragDropProvider>\n  <DropZone id=\"list\" label=\"Tasks\">\n    <Column snug>\n      <Draggable id=\"a\" data={{ id: \"a\", zone: \"list\" }} label=\"Design review\">\n        <Card>\n          <Row between alignCenter>\n            <Typography>Design review</Typography>\n            <DragHandle label=\"Reorder Design review\" />\n          </Row>\n        </Card>\n      </Draggable>\n      <Draggable id=\"b\" data={{ id: \"b\", zone: \"list\" }} disabled label=\"Locked task\">\n        <Card>\n          <Row between alignCenter>\n            <Typography>Locked task</Typography>\n            <DragHandle label=\"Locked task\" />\n          </Row>\n        </Card>\n      </Draggable>\n    </Column>\n  </DropZone>\n</DragDropProvider>", render: e_organisms_drag_drop_example_1 },
      { label: "Between columns", code: "<Stateful initial={[\n  { id: \"t1\", zone: \"todo\", title: \"Rotate secrets\" },\n  { id: \"t2\", zone: \"todo\", title: \"Draft the review\" },\n  { id: \"t3\", zone: \"doing\", title: \"SSO rollout\" },\n  { id: \"t4\", zone: \"doing\", title: \"Audit log export\" },\n]}>\n  {(cards, setCards) => (\n    <DragDropProvider>\n      <Grid columns={2} relaxed>\n        {[\"todo\", \"doing\"].map((zone) => (\n          <DropZone key={zone} id={zone} label={zone === \"todo\" ? \"To do\" : \"Doing\"} onDrop={(e) => setCards(applyDrop(cards, e))}>\n            <Column snug>\n              {cards.filter((c) => c.zone === zone).map((c) => (\n                <Draggable key={c.id} id={c.id} data={c} label={c.title}>\n                  <Card>\n                    <Row between alignCenter>\n                      <Typography>{c.title}</Typography>\n                      <DragHandle label={`Reorder ${c.title}`} />\n                    </Row>\n                  </Card>\n                </Draggable>\n              ))}\n            </Column>\n          </DropZone>\n        ))}\n      </Grid>\n    </DragDropProvider>\n  )}\n</Stateful>", render: e_organisms_drag_drop_example_2 },
    ],
    donts: [
      { title: "Grip and fallback", do: { caption: "Give each item a labeled `DragHandle` and keep a non-drag way to move it. The grip is a keyboard tab stop that grabs on Space and moves with the arrows; a `RowMenu` \"Move to\" beside it is a good extra path for pointer and assistive-tech users.", code: "<DragDropProvider>\n  <DropZone id=\"list\" label=\"Tasks\" style={{ width: 280, maxWidth: \"100%\", minHeight: 96 }}>\n    <Draggable id=\"a\" data={{ id: \"a\", zone: \"list\" }} label=\"Design review\">\n      <Card compact>\n        <Row between alignCenter>\n          <Typography small>Design review</Typography>\n          <Row snug alignCenter>\n            <DragHandle label=\"Reorder Design review\" />\n            <RowMenu items={[{ label: \"Move to Doing\", icon: \"arrowRight\" }]} triggerLabel=\"Move Design review\" />\n          </Row>\n        </Row>\n      </Card>\n    </Draggable>\n  </DropZone>\n</DragDropProvider>", render: e_organisms_drag_drop_dont_0_do }, dont: { caption: "Don't make a bare card the only drag surface with no grip and no alternative: whole-card dragging fights taps and scrolling, and it leaves keyboard and screen-reader users with no way to move the item at all.", code: "<Card compact>\n  <Pressable onPress={() => {}}>\n    <Typography small>Design review (drag the whole card?)</Typography>\n  </Pressable>\n</Card>", render: e_organisms_drag_drop_dont_0_dont } },
    ],
  },
